#!/usr/bin/env bash
# Upgrade rehearsal harness for Alfresco Community Docker Compose environments
# generated by alfresco-docker-installer (test/envs/<version>).
#
# Commands:
#   start <env>              start repository, database and search, wait until ready
#   stop <env>               stop and remove containers (data folders are kept)
#   seed                     create the test data set in the running repository
#   verify <label>           check the test data set, upload a new document, check its PDF rendition
#   snapshot <env> <name>    dump database and copy content store to snapshots/<name>
#   restore <name> <env>     load snapshots/<name> into a clean <env>
#   search <label> [env]     full-text search for old content and the new document from verify;
#                            with <env>, fails at once if a search service stops
#   reindex <env> [gap]      initial index of existing content: seed cursor, catch up (26.2); gap = maxGapAge, default 0
#   age <env> <days>         move all transaction times back <days> days (simulates an old repository)
set -euo pipefail

ROOT="$(cd "$(dirname "$0")" && pwd)"
ENVS="$ROOT/envs"
SNAP="$ROOT/snapshots"
RES="$ROOT/results"
FIX="$ROOT/fixtures"
URL="http://localhost:8081/alfresco"
API="$URL/api/-default-/public/alfresco/versions/1"
AUTH="admin:admin"
SITE="upgrade-test"

token() { echo "newtoken$(echo "$1" | tr -cd '[:alnum:]' | tr '[:upper:]' '[:lower:]')"; }
log() { printf '[%s] %s\n' "$(date +%H:%M:%S)" "$*"; }
project() { echo "acs$(echo "$1" | tr -d '.')"; }
dc() { local env="$1"; shift; docker compose -p "$(project "$env")" --project-directory "$ENVS/$env" "$@"; }

services() {
  local f="$ENVS/$1/docker-compose.yml" s="postgres alfresco"
  grep -q '^    transform-core-aio:' "$f" && s="$s transform-core-aio"
  grep -q '^    solr6:' "$f" && s="$s solr6"
  grep -q '^    opensearch:' "$f" && s="$s opensearch activemq batch-indexer"
  echo "$s"
}

wait_db() {
  local env="$1"
  for _ in $(seq 1 60); do
    dc "$env" exec -T postgres pg_isready -U alfresco >/dev/null 2>&1 && return 0
    sleep 2
  done
  log "postgres not ready"; return 1
}

wait_repo() {
  local env="$1" code
  for i in $(seq 1 "${READY_TRIES:-180}"); do
    code=$(curl -s -o /dev/null -w '%{http_code}' -u "$AUTH" "$URL/api/discovery" || true)
    if [ "$code" = "200" ]; then log "repository ready after $((i * 5))s"; return 0; fi
    if [ -z "$(dc "$env" ps -q --status running alfresco)" ]; then log "alfresco container stopped"; return 1; fi
    sleep 5
  done
  log "repository not ready after $((${READY_TRIES:-180} * 5))s"; return 1
}

cmd_start() {
  local env="$1"
  mkdir -p "$ENVS/$env/data/alf-repo-data" "$ENVS/$env/logs"
  # shellcheck disable=SC2046
  dc "$env" up -d --build $(services "$env")
  wait_repo "$env"
}

cmd_stop() { dc "$1" down --remove-orphans; }

post_json() { curl -sf -u "$AUTH" -H 'Content-Type: application/json' -X POST "$1" -d "$2"; }
jget() { python3 -I -c "import json,sys; d=json.load(sys.stdin); print(eval(sys.argv[1], {'d': d}))" "$1"; }

cmd_seed() {
  log "seeding"
  post_json "$API/sites" "{\"id\":\"$SITE\",\"title\":\"Upgrade test\",\"visibility\":\"PUBLIC\"}" >/dev/null
  post_json "$API/people" '{"id":"upgrade.user","firstName":"Upgrade","lastName":"User","email":"upgrade.user@example.com","password":"upgrade"}' >/dev/null
  local lib folder doc bin
  lib=$(curl -sf -u "$AUTH" "$API/sites/$SITE/containers/documentLibrary" | jget "d['entry']['id']")
  folder=$(post_json "$API/nodes/$lib/children" '{"name":"Upgrade folder","nodeType":"cm:folder"}' | jget "d['entry']['id']")
  doc=$(curl -sf -u "$AUTH" -X POST "$API/nodes/$folder/children" -F "filedata=@$FIX/doc1.txt" -F "name=doc1.txt" | jget "d['entry']['id']")
  curl -sf -u "$AUTH" -X PUT -H 'Content-Type: text/plain' "$API/nodes/$doc/content?majorVersion=true" --data-binary "@$FIX/doc1-v2.txt" >/dev/null
  bin=$(curl -sf -u "$AUTH" -X POST "$API/nodes/$folder/children" -F "filedata=@$FIX/binary.bin" -F "name=binary.bin" | jget "d['entry']['id']")
  post_json "$API/nodes/$doc/comments" '{"content":"Comment added before upgrade"}' >/dev/null
  # On 6.1 the first tag request right after a version update can be lost, so check and retry.
  for _ in 1 2 3; do
    post_json "$API/nodes/$doc/tags" '{"tag":"upgradetag"}' >/dev/null
    curl -sf -u "$AUTH" "$API/nodes/$doc/tags" | grep -q '"upgradetag"' && break
    sleep 5
  done
  curl -sf -u "$AUTH" -X PUT -H 'Content-Type: application/json' "$API/nodes/$bin" \
    -d '{"properties":{"cm:title":"Binary title","cm:description":"Binary description"}}' >/dev/null
  log "seed done: site=$SITE folder=$folder doc=$doc bin=$bin"
}

cmd_verify() {
  local label="$1" out fails=0 node v
  mkdir -p "$RES"; out="$RES/$label.txt"; : > "$out"
  check() { if [ "$2" = "$3" ]; then echo "PASS $1" >> "$out"; else echo "FAIL $1 (expected '$3', got '$2')" >> "$out"; fails=$((fails + 1)); fi; }
  curl -sf -u "$AUTH" "$URL/api/discovery" | jget "'version: ' + d['entry']['repository']['version']['display'] + ' schema=' + str(d['entry']['repository']['version']['schema'])" >> "$out"
  check "site exists" "$(curl -s -o /dev/null -w '%{http_code}' -u "$AUTH" "$API/sites/$SITE")" 200
  check "user exists" "$(curl -s -o /dev/null -w '%{http_code}' -u "$AUTH" "$API/people/upgrade.user")" 200
  check "user can log in" "$(curl -s -o /dev/null -w '%{http_code}' -u upgrade.user:upgrade "$API/people/-me-")" 200
  local base="relativePath=Sites/$SITE/documentLibrary/Upgrade%20folder"
  node=$(curl -sf -u "$AUTH" "$API/nodes/-root-?$base/doc1.txt" | jget "d['entry']['id']")
  check "doc1 content (latest version)" "$(curl -sf -u "$AUTH" "$API/nodes/$node/content" | shasum -a 256 | cut -c1-64)" "$(shasum -a 256 < "$FIX/doc1-v2.txt" | cut -c1-64)"
  v=$(curl -sf -u "$AUTH" "$API/nodes/$node/versions" | jget "len(d['list']['entries'])")
  check "doc1 version count" "$v" 2
  check "doc1 version 1.0 content" "$(curl -sf -u "$AUTH" "$API/nodes/$node/versions/1.0/content" | shasum -a 256 | cut -c1-64)" "$(shasum -a 256 < "$FIX/doc1.txt" | cut -c1-64)"
  check "doc1 comment" "$(curl -sf -u "$AUTH" "$API/nodes/$node/comments" | jget "d['list']['entries'][0]['entry']['content']")" "Comment added before upgrade"
  check "doc1 tag" "$(curl -sf -u "$AUTH" "$API/nodes/$node/tags" | jget "'upgradetag' in [e['entry']['tag'] for e in d['list']['entries']]")" "True"
  node=$(curl -sf -u "$AUTH" "$API/nodes/-root-?$base/binary.bin" | jget "d['entry']['id']")
  check "binary content" "$(curl -sf -u "$AUTH" "$API/nodes/$node/content" | shasum -a 256 | cut -c1-64)" "$(shasum -a 256 < "$FIX/binary.bin" | cut -c1-64)"
  check "binary title" "$(curl -sf -u "$AUTH" "$API/nodes/$node" | jget "d['entry']['properties']['cm:title']")" "Binary title"
  # New document after the upgrade: upload, then PDF rendition. Search is checked by "search <label>".
  local tmp code status
  tmp="$(mktemp)"; printf 'Document uploaded after the upgrade.\nUnique token: %s\n' "$(token "$label")" > "$tmp"
  node=$(curl -sf -u "$AUTH" -X POST "$API/nodes/-my-/children" -F "filedata=@$tmp;type=text/plain" -F "name=after-$label.txt" -F "autoRename=true" | jget "d['entry']['id']" || true)
  rm -f "$tmp"
  check "upload after upgrade" "$([ -n "$node" ] && echo ok)" ok
  # Right after startup the repository may not have loaded the transform config yet (404), so retry.
  for _ in $(seq 1 24); do
    code=$(curl -s -o /dev/null -w '%{http_code}' -u "$AUTH" -H 'Content-Type: application/json' -X POST "$API/nodes/$node/renditions" -d '{"id":"pdf"}')
    [ "$code" = "202" ] && break
    sleep 5
  done
  check "pdf rendition requested" "$code" 202
  status=""
  for _ in $(seq 1 60); do
    status=$(curl -s -u "$AUTH" "$API/nodes/$node/renditions/pdf" | jget "d['entry']['status']" 2>/dev/null || true)
    [ "$status" = "CREATED" ] && break
    sleep 5
  done
  check "pdf rendition created" "$status" CREATED
  check "pdf rendition is a PDF" "$(curl -s -u "$AUTH" "$API/nodes/$node/renditions/pdf/content" | head -c 4)" "%PDF"
  cat "$out"
  [ "$fails" -eq 0 ]
}

running() { [ -n "$(dc "$1" ps -q --status running "$2")" ]; }

# Search services that must be running in <env>. Fails fast, with the last log lines, if one stopped.
search_alive() {
  local env="$1" svc list
  if grep -q '^    opensearch:' "$ENVS/$env/docker-compose.yml"; then list="${2:-opensearch batch-indexer}"; else list="solr6"; fi
  for svc in $list; do
    if ! running "$env" "$svc"; then
      log "FAIL $svc is not running"
      dc "$env" logs --tail 8 "$svc" 2>&1 | grep -vE '^\S+\s+\|\s+at ' | cut -c1-220
      return 1
    fi
  done
}

cmd_search() {
  # Old content (seeded before the upgrade) and the document uploaded by "verify <label>".
  local label="$1" env="${2:-}" out t n i fails=0
  out="$RES/$label-search.txt"; : > "$out"
  for t in upgradetoken42 "$(token "$label")"; do
    n=0
    for i in $(seq 1 "${SEARCH_TRIES:-60}"); do
      [ -z "$env" ] || search_alive "$env" || { echo "FAIL search '$t': search service stopped" >> "$out"; cat "$out"; return 1; }
      n=$(curl -s -u "$AUTH" -H 'Content-Type: application/json' -X POST "$URL/api/-default-/public/search/versions/1/search" \
        -d "{\"query\":{\"query\":\"$t\",\"language\":\"afts\"}}" | jget "d['list']['pagination']['totalItems']" 2>/dev/null || echo 0)
      [ "${n:-0}" -ge 1 ] && break
      sleep 10
    done
    if [ "${n:-0}" -ge 1 ]; then echo "PASS search '$t' found $n result(s) after $((i * 10))s" >> "$out"
    else echo "FAIL search '$t' found no results after $((${SEARCH_TRIES:-60} * 10))s" >> "$out"; fails=$((fails + 1)); fi
  done
  cat "$out"
  [ "$fails" -eq 0 ]
}

os_curl() { local env="$1"; shift; dc "$env" exec -T opensearch curl -s "$@"; }
cursor() { os_curl "$1" "localhost:9200/alfresco-reindex-state/_doc/reindexByDate-watermark" | jget "d['_source']['lastSuccessfulToTimeEpochMs']" 2>/dev/null || echo 0; }
doc_count() { os_curl "$1" "localhost:9200/alfresco/_count" | jget "d['count']" 2>/dev/null || echo 0; }

cmd_reindex() {
  # Initial index of existing content (Search Community guide, "Migrating from Solr to OpenSearch").
  # On first start the batch indexer only indexes from "now - overlap". The fix: seed the cursor from
  # the first repository transaction, and run a catch-up with maxGapAge=0 (otherwise a cursor older
  # than 24 h is skipped) and a large maxWindow (catch-up walks calendar windows).
  # Progress is checked all the time: the step fails at once if OpenSearch or the indexer stops,
  # or if neither the cursor nor the document count moves for STALL seconds.
  local env="$1" gap="${2:-0}" stall="${STALL:-90}" t start to docs prev changed now cid nodes dlq ok=0
  t=$(dc "$env" exec -T postgres psql -U alfresco -tAc "select min(commit_time_ms) - 60000 from alf_transaction")
  # The state index and the watermark document are created by the first indexing cycle.
  for _ in $(seq 1 60); do
    search_alive "$env" || return 1
    os_curl "$env" -f "localhost:9200/alfresco-reindex-state/_doc/reindexByDate-watermark" >/dev/null 2>&1 && break
    sleep 5
  done
  dc "$env" stop batch-indexer
  local put="" i
  for i in $(seq 1 12); do
    put=$(os_curl "$env" -w ' HTTP %{http_code}' -X PUT "localhost:9200/alfresco-reindex-state/_doc/reindexByDate-watermark?refresh=true" \
      -H 'Content-Type: application/json' -d "{\"schemaVersion\":1,\"lastSuccessfulToTimeEpochMs\":$t}")
    case "$put" in *' HTTP 20'?) break ;; esac
    sleep 5
  done
  case "$put" in
    *' HTTP 20'?) [ "$i" -gt 1 ] && log "cursor written after $i attempts" ;;
    *) log "FAIL cannot write the cursor: $(echo "$put" | cut -c1-300)"; dc "$env" up -d --no-deps batch-indexer; return 1 ;;
  esac
  start=$(( $(date +%s) * 1000 ))
  log "cursor seeded at $t; starting catch-up (MAXGAPAGE=$gap, MAXWINDOW=7d)"
  cid=$(dc "$env" run -d --no-deps \
    -e ALFRESCO_REINDEX_CONTINUOUS_MAXGAPAGE="$gap" -e ALFRESCO_REINDEX_CONTINUOUS_MAXWINDOW=7d batch-indexer)
  prev="" changed=$(date +%s)
  while :; do
    now=$(date +%s)
    search_alive "$env" opensearch || break
    if [ "$(docker inspect -f '{{.State.Running}}' "$cid" 2>/dev/null)" != "true" ]; then
      log "FAIL catch-up indexer stopped"; docker logs --tail 8 "$cid" 2>&1 | cut -c1-220; break
    fi
    to=$(cursor "$env"); docs=$(doc_count "$env")
    [ "$to $docs" != "$prev" ] && { prev="$to $docs"; changed=$now; }
    [ $(( (now - start / 1000) % 30 )) -lt 5 ] && log "progress: cursor=$(date -u -r $(( ${to:-0} / 1000 )) '+%Y-%m-%d %H:%M') docs=$docs"
    [ "${to:-0}" -ge "$start" ] && { ok=1; break; }
    if [ $(( now - changed )) -ge "$stall" ]; then log "FAIL no progress for ${stall}s (cursor and document count unchanged)"; break; fi
    sleep 5
  done
  docker rm -f "$cid" >/dev/null
  dc "$env" up -d --no-deps batch-indexer
  [ "$ok" -eq 1 ] || return 1
  log "catch-up done in $(( $(date +%s) - start / 1000 ))s"
  nodes=$(dc "$env" exec -T postgres psql -U alfresco -tAc \
    "select count(*) from alf_node n join alf_store s on s.id = n.store_id where s.protocol = 'workspace' and s.identifier = 'SpacesStore'")
  os_curl "$env" -X POST "localhost:9200/alfresco/_refresh" >/dev/null
  docs=$(doc_count "$env")
  dlq=$(os_curl "$env" "localhost:9200/alfresco-reindex-dead-letter/_count?expand_wildcards=all" | jget "d.get('count', 0)" 2>/dev/null || echo 0)
  log "index docs=$docs, SpacesStore nodes=$nodes, dead letters=$dlq"
  # The cursor reaching "now" is not enough: with maxGapAge > 0 old history is skipped and the
  # cursor still advances. Require the index to cover at least 95% of the SpacesStore nodes.
  [ $(( ${docs:-0} * 100 )) -ge $(( ${nodes:-1} * 95 )) ] || { log "FAIL index covers less than 95% of the nodes"; return 1; }
}

cmd_age() {
  # Simulates an old repository: moves every transaction commit time back <days> days.
  local env="$1" days="$2"
  dc "$env" exec -T postgres psql -U alfresco -tAc \
    "update alf_transaction set commit_time_ms = commit_time_ms - $days::bigint * 86400000" >/dev/null
  log "transactions moved back $days days: $(dc "$env" exec -T postgres psql -U alfresco -tAc \
    "select to_timestamp(min(commit_time_ms) / 1000)::date || ' to ' || to_timestamp(max(commit_time_ms) / 1000)::date from alf_transaction")"
}

cmd_snapshot() {
  local env="$1" name="$2"
  mkdir -p "$SNAP/$name"
  curl -sf -u "$AUTH" "$URL/api/discovery" | jget "d['entry']['repository']['version']['display']" > "$SNAP/$name/version.txt"
  dc "$env" stop alfresco
  dc "$env" exec -T postgres pg_dump -U alfresco -Fc alfresco > "$SNAP/$name/alfresco.dump"
  rm -rf "$SNAP/$name/alf-repo-data"
  cp -a "$ENVS/$env/data/alf-repo-data" "$SNAP/$name/alf-repo-data"
  log "snapshot $name: $(cat "$SNAP/$name/version.txt"), $(du -sh "$SNAP/$name" | cut -f1)"
}

cmd_restore() {
  local name="$1" env="$2"
  dc "$env" down --remove-orphans >/dev/null 2>&1 || true
  rm -rf "$ENVS/$env/data" "$ENVS/$env/logs"
  mkdir -p "$ENVS/$env/data" "$ENVS/$env/logs"
  cp -a "$SNAP/$name/alf-repo-data" "$ENVS/$env/data/alf-repo-data"
  dc "$env" up -d postgres
  wait_db "$env"
  # pg_dump includes "CREATE SCHEMA public", which fails on a new database. That error is harmless.
  dc "$env" exec -T postgres pg_restore -U alfresco -d alfresco --no-owner < "$SNAP/$name/alfresco.dump" || true
  log "restored nodes: $(dc "$env" exec -T postgres psql -U alfresco -tAc 'select count(*) from alf_node')"
  log "restored $name into $env"
}

cmd="${1:-}"; shift || true
case "$cmd" in
  start|stop|seed|verify|search|reindex|age|snapshot|restore) "cmd_$cmd" "$@" ;;
  *) sed -n '2,15p' "$0"; exit 1 ;;
esac
